  assert.equal(proof.probes[0].exit, 1);
  assert.equal(
    calls.some((argv) => argv.join(" ").includes("linux-runtime")),
    false,
  );
  for (const bad of [
    { ...record, run },
    { ...record, packet: join(run, "prepared", "other") },
