      ...record,
      cli: {
        ...record.cli,
        args: ["-C", join(run, "prepared", "other")],
      },
    },
  ]) {
    assert.equal(
      (await review.probeSharedReviewer(common, run, bad, harness)).stopped,
      false,
    );
  }
  assert.equal(calls.length, 1);
  const wrong = join(common, "frade-workflow", "runs", "runs");
