    id: "S03",
    change: "second-change",
  });
  manifest.scope.planningAllowed.push("openspec/changes/second-change/**");
  manifest.originalBaseline = await git(f.root, "rev-parse", "HEAD");
  const request = {
    ...f.request,
    change: "second-direction",
    stage: "S02",
    task: "3.1",
    paths: [...f.request.paths, sourcePath, decisionPath],
  };
  const authority = createRoleAuthority({
    bindings: [
      { path: sourcePath, sha256: hash(source), revision: "S02-approved" },
      { path: decisionPath, sha256: hash(decision), revision: "S02-approved" },
    ],
    verifyApproval: async ({ assignment, rawDecision }) =>
      rawDecision.bytes.toString("utf8") === decision &&
      assignment.model === "gpt-5.5" &&
      assignment.effort === "high",
  });
  const admission = api.createReviewAdmission({
    authority,
    policySha256: hash(f.policy),
    allowedPaths: ["AGENTS.md", ...manifest.scope.allowed],
    requiredPaths: [sourcePath, decisionPath],
    verifyPlan: async ({ reader }) =>
      (await reader.read(decisionPath)).sha256 === hash(decision),
  });
  const ready = await api.prepareReview({ ...f, manifest, request, admission });
  assert.equal(ready.status, "READY", JSON.stringify(ready));
  assert.equal(ready.assignment.model, "gpt-5.5");
  assert.equal(ready.assignment.effort, "high");
  const otherRequest = {
    ...request,
    stage: "S03",
    change: "second-change",
    task: "3.2",
  };
  assert.equal(
    (
      await api.prepareReview({
        ...f,
        manifest,
        request: otherRequest,
        admission,
      })
    ).status,
    "READY",
  );
  const lock = join(f.root, ".git/frade-workflow/freeze/second-direction.json");
  await mkdir(join(lock, ".."), { recursive: true });
  await writeFile(
    lock,
    JSON.stringify({
      directionId: manifest.id,
      stageId: "S03",
      owningChange: otherRequest.change,
    }),
  );
  const locked = await run({ ...f, manifest, request, admission }, complete());
  assert.equal(locked.status, "BLOCKED", JSON.stringify(locked));
  assert.match(locked.code, /EEXIST/);
  assert.equal(
    await readFile(lock, "utf8"),
    JSON.stringify({
      directionId: manifest.id,
      stageId: "S03",
      owningChange: otherRequest.change,
    }),
  );
  await rm(lock);
  const received = await run(
    { ...f, manifest, request, admission },
    complete(),
  );
  assert.equal(received.status, "PASS", JSON.stringify(received));
  assert.equal(received.closureAuthorized, false);
  assert.equal(received.assignment.stage, "S02");
  assert.equal(received.actualBackend, "NOT_CONFIRMED");
  assert.equal(received.actualEffort, "NOT_CONFIRMED");
  assert.equal(
    (await api.prepareReview({ ...f, manifest, request })).status,
    "BLOCKED",
  );
  assert.equal(
    (
      await api.prepareReview({
        ...f,
        manifest,
        request,
        admission: { approved: true },
      })
    ).status,
    "BLOCKED",
  );
  assert.equal(
    (
      await api.prepareReview({
        ...f,
        manifest,
        request: { ...request, approved: true },
      })
    ).status,
    "BLOCKED",
  );
  assert.equal(
    (
      await api.prepareReview({
        ...f,
        manifest,
        request: { ...request, approval: { approved: true } },
        admission,
      })
    ).status,
    "BLOCKED",
  );
  const widened = structuredClone(manifest);
  widened.scope.allowed.push("other-owner/**");
  assert.equal(
    (await api.prepareReview({ ...f, manifest: widened, request, admission }))
      .status,
    "BLOCKED",
  );
  await writeFile(
    join(f.root, sourcePath),
    "| S02 | independent-POST | gpt-6-astra | xhigh |\n",
  );
  assert.equal(
    (await api.prepareReview({ ...f, manifest, request, admission })).status,
    "BLOCKED",
  );
});

