export const COMMON = 'E:/dev/codex/frade/.git'
export const sha = (value) => createHash('sha256').update(value).digest('hex')
const git = (cwd, args) =>
  execFileSync('git', ['-c', 'core.longpaths=true', ...args], {
    cwd,
    encoding: 'utf8',
